package br.com.marquesautodetail.api.servico;
import br.com.marquesautodetail.api.empresa.Empresa;import jakarta.persistence.*;import java.math.BigDecimal;
@Entity @Table(name="servicos") public class Servico{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String nome; @Column(length=1000) private String descricao; @Column(nullable=false) private BigDecimal preco; private Integer duracaoMinutos; private Boolean ativo=true; @ManyToOne @JoinColumn(name="empresa_id") private Empresa empresa; public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getNome(){return nome;} public void setNome(String nome){this.nome=nome;} public String getDescricao(){return descricao;} public void setDescricao(String descricao){this.descricao=descricao;} public BigDecimal getPreco(){return preco;} public void setPreco(BigDecimal preco){this.preco=preco;} public Integer getDuracaoMinutos(){return duracaoMinutos;} public void setDuracaoMinutos(Integer duracaoMinutos){this.duracaoMinutos=duracaoMinutos;} public Boolean getAtivo(){return ativo;} public void setAtivo(Boolean ativo){this.ativo=ativo;} public Empresa getEmpresa(){return empresa;} public void setEmpresa(Empresa empresa){this.empresa=empresa;} }
